raste funcional: BLOQUEAR cierre de pantalla B2B sin variantes desktop, tablet y móvil según lf_design.responsive_tokens vigentes; no inventar breakpoints.","residual":"","complementa":null},{"codigo":"S11-C24","version":1,"eval_id":889,"hash_version_atestado":"b4fc35dffa66aac6765b0ba9a2e97aa7a5f8fd48d4f7607dfcb5b10e0d81c6e5","hash_paquete_atestado":"6bdcad4f38bd9ce0e1ea1ebd4a1b7ad374358d1ab56d72856204a34bbf277752","veredicto":"PASS","juez":"Claude independiente 2026-11-24 05:55 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":392,"familia":"RESPONSIVE","diferencias":"Contraste funcional: BLOQUEAR shell B2B que no admita expandido/contraído en desktop, no inicie contraído en tablet o no use drawer en móvil, según breakpoint canónico.","residual":"","complementa":null},{"codigo":"S11-C25","version":1,"eval_id":890,"hash_version_atestado":"ac7d099a1b78890bdcf0c65dbe5a3cd35aaccf803036b91edee1002e58c5d011","hash_paquete_atestado":"d6eeb9ffe01679229bd1272de84f9499f300f77ee220213b8a921c0b6ccb7931","veredicto":"PASS","juez":"Claude independiente 2026-11-24 05:55 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":393,"familia":"RESPONSIVE","diferencias":"Contraste funcional: BLOQUEAR tabla B2B en móvil que no priorice columnas esenciales según contrato de tabla o no permita expandir detalle.","residual":"","complementa":null}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA' AND hash=p->>'hash_version_atestado') THEN RAISE EXCEPTION 'S11_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S11_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s11_juicios_25_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S11_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision'<>'AUTO' THEN RAISE EXCEPTION 'S11_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S11_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S11_COVERAGE_DRIFT %',lid; END IF;
 IF p->>'complementa' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo WHERE c.legacy_id=lid AND c.nucleo_codigo=p->>'complementa' AND c.estado_cobertura='PARCIAL' AND v.estado='PUBLICADA') THEN RAISE EXCEPTION 'S11_COMPLEMENT_DRIFT %',lid; END IF;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 residual:=coalesce(p->>'residual',''); diff:=p->>'diferencias'||CASE WHEN residual<>'' THEN ' Residual: '||residual ELSE '' END;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,CASE WHEN residual='' THEN 'REEMPLAZADA' ELSE 'PARCIAL' END,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S11 2026-11-24 05:55','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S11 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S11_SOURCE_MISSING %',lid; END IF;
 n:=n+1;
 END LOOP;
 IF n<>25 OR pub<>25 OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>25) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S11_READBACK_FAIL n=% pub=% links=%',n,pub,links; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S11_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S11_PASS 25 JUICIOS 25 AUTO links=% DPIG03=0',links;
END $s11$;
COMMIT;
